'use strict';
const M=ReportsModel, V=Number(document.body.dataset.variation), $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>'₹ '+Number(x).toLocaleString('en-IN');
const icon=(name='report')=>{const p={report:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M8 2v4m8-4v4M8 11h8m-8 4h5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 16v4h14v-4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',back:'<path d="m10 5-7 7 7 7M3 12h18"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',check:'<path d="m4 12 5 5L20 6"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.report}</svg>`;};
const btn=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const opt=(values,value)=>values.map(x=>`<option value="${esc(x)}" ${String(x)===String(value)?'selected':''}>${esc(x)}</option>`).join('');
let saved;try{saved=JSON.parse(localStorage.getItem('wealthy-prototype-v'+V));}catch{}
const initialSchedule={id:'seed',report:'mf',ids:[1,2],config:{...M.defaults(M.reports[4]),delivery:'Schedule',name:'Monthly portfolio update',period:'Last month'},status:'Active'};
let S={screen:'catalog',category:'client',tab:'all',report:null,ids:[],config:null,clientTab:'all',search:'',catalogSearch:'',page:1,rows:10,sort:'id',direction:1,filters:[],draftFilters:[],modal:null,returnModal:null,edit:null,busy:false,result:null,history:saved?.history||[],schedules:saved?.schedules||[initialSchedule],expanded:null,qa:{outcome:'success',list:'normal'},notice:'',listLoading:false,selectedOnly:false,records:{schedules:{page:1,rows:20},history:{page:1,rows:20}}};
let focusReturn=null,toastTimer;
function persist(){try{localStorage.setItem('wealthy-prototype-v'+V,JSON.stringify({history:S.history,schedules:S.schedules}));}catch{}}
function toast(t){$('#toast').className='toast';$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},3500);}
function report(){return M.reports.find(r=>r.id===S.report);}
function chosen(){return S.ids.map(id=>M.clients.find(c=>c.id===id)).filter(Boolean);}
function countLabel(n=S.ids.length){return n+' '+(n===1?'client':'clients');}
function showModal(type){focusReturn=document.activeElement?.id||null;S.modal=type;renderOverlay(true);}
function closeModal(){if(S.busy)return;S.modal=S.returnModal||null;S.returnModal=null;renderOverlay(true);if(!S.modal){document.getElementById(focusReturn)?.focus();}}
function shell(){return `<div class="prototype-bar"><div class="row"><a href="index.html">← Compare</a><a class="${V===1?'active':''}" href="variation-1.html">1 · Split screen</a><a class="${V===2?'active':''}" href="variation-2.html">2 · Modal</a><span class="proto-description">Interactive prototype · Sample data only</span></div>${btn('Prototype controls','controls','','id="controls-trigger"')}</div><aside class="sidebar" aria-label="Application navigation"><div class="brand"><img src="assets/wealthy.svg" alt="Wealthy"></div><div class="store">${icon('users')} Wealthy Store<p>Explore our diverse<br>range of products</p><span class="primary" style="display:block;text-align:center;border-radius:7px;padding:10px">Explore Store</span></div>${[['Home','a97dc20521b28d75'],['Clients List','213356180d78d4d0'],['Systematic Plans','661d56bc24ce181b'],['Transactions','a97dc20521b28d75'],['Proposals','213356180d78d4d0'],['Reports','3012eed4556fad9e'],['My Team','53024693db1a398f'],['Smart Tools','3012eed4556fad9e'],['Earnings','a97dc20521b28d75'],['LAMF','53024693db1a398f'],['Resources','213356180d78d4d0'],['My Profile','53024693db1a398f']].map(([t,i])=>`<div class="navitem ${t==='Reports'?'current':''}" ${t==='Reports'?'aria-current="page"':''}><img src="assets/${i}.svg" alt=""><span>${t}</span></div>`).join('')}</aside><header class="topbar"><div class="topsearch">${icon('search')} Search clients, funds, pages…</div><div class="row"><span class="top-extra muted">Refer and Earn</span><div class="profile">Partner workspace<small style="display:block">Demo account</small></div></div></header><main class="main" id="main">${S.screen==='catalog'?catalog():workspace()}</main>`;}
function catalog(){const rr=M.reports.filter(r=>r.business===(S.category==='business')&&(r.name+' '+r.description).toLowerCase().includes(S.catalogSearch.toLowerCase()));return `<div class="catalog-head"><h1>Reports</h1><p class="muted">Schedule, email, or download reports for many clients at once</p><div class="segment" role="group" aria-label="Report category">${['client','business'].map(c=>btn(c==='client'?'Client Report':'Business Report','category',S.category===c?'on':'',`data-value="${c}" aria-pressed="${S.category===c}"`)).join('')}</div></div><div class="tabrow"><div class="tabs" role="tablist" aria-label="Reports views">${btn('All reports','tab','tab '+(S.tab==='all'?'on':''),'role="tab" aria-selected="'+(S.tab==='all')+'" data-value="all"')}${S.category==='client'?btn('Schedules ('+S.schedules.length+')','tab','tab '+(S.tab==='schedules'?'on':''),'role="tab" aria-selected="'+(S.tab==='schedules')+'" data-value="schedules"'):''}${btn('History ('+S.history.filter(j=>j.business===(S.category==='business')).length+')','tab','tab '+(S.tab==='history'?'on':''),'role="tab" aria-selected="'+(S.tab==='history')+'" data-value="history"')}</div>${S.tab==='all'?`<input id="catalog-search" class="search" placeholder="Search by name" aria-label="Search reports" value="${esc(S.catalogSearch)}" data-input="catalogSearch">`:''}</div>${S.tab==='all'?`<div class="cards">${rr.map(r=>`<button type="button" class="card" data-action="report" data-value="${r.id}"><div class="card-top"><span class="tile-icon">${icon()}</span><span>›</span></div><strong>${r.name}</strong><p>${r.description}</p><small>${r.formats.join(' · ')}</small></button>`).join('')}</div>${rr.length?'':`<div class="empty"><h3>No reports found</h3><p>Try another report name.</p>${btn('Clear search','clear-catalog','ghost')}</div>`}`:S.tab==='schedules'?scheduleTable():historyTable()}<footer class="footer">2026 © Wealthy</footer>`;}
function openReport(id){S.report=id;S.config=M.defaults(report());S.screen='work';S.ids=[];S.edit=null;S.search='';S.page=1;S.filters=[];S.clientTab='all';S.selectedOnly=false;S.notice='';S.modal=report().business&&V===2?'config':null;S.listLoading=true;render();window.scrollTo(0,0);setTimeout(()=>{S.listLoading=false;render();},420);}
function workspace(){const r=report();return `${btn(icon('back')+' Reports','back','back','id="back-reports"')}<div class="workhead"><div><h1>${r.name}</h1><small class="muted">${r.business?'Configure your business report.':V===1?'Select clients and configure your report in one place.':'Select clients, then configure your report without leaving this page.'}</small></div><span class="badge purple">${S.edit?'Edit schedule':V===1?'Select & configure':'Choose clients'}</span></div>${V===1?`<div class="workspace"><section class="client-pane">${r.business?businessScope():clientPane()}</section><aside class="panel" id="configuration-panel" aria-label="Report configuration"><div class="panel-head"><div><h3>${S.edit?'Edit schedule':'Configure report'}</h3><p>${r.business?'Business scope':btn(countLabel()+' selected · Review','review-selected','ghost selected-header')}</p></div></div><div class="panel-body" id="panel-scroll">${configuration()}${selectedSummary()}${reviewSummary()}</div><div class="panel-footer" id="panel-footer">${actionFooter(false)}</div></aside></div>`:`<section class="full-client">${r.business?businessScope():clientPane()}</section><div class="sticky-selection"><div class="row"><span class="tile-icon">${icon()}</span><div><strong>${r.business?'Business report':countLabel()+' selected'}</strong><small class="selection-report" style="display:block">${r.name}</small></div>${!r.business&&S.ids.length?btn('Review selection','review-selected','ghost'):''}</div>${btn('Configure report →','configure','primary',`id="configure-trigger" ${!r.business&&!S.ids.length?'disabled':''}`)}</div>`}`;}
function businessScope(){return `<div class="business-scope"><span class="tile-icon">${icon('users')}</span><h2 style="margin-top:16px">Your business, in one report</h2><p class="muted">${report().description}</p><div class="notice" style="margin:20px 0">This report covers your business. Client selection does not apply to this report type.</div><dl class="summary-lines"><dt>Report</dt><dd>${report().name}</dd><dt>Available action</dt><dd>Download</dd><dt>Formats</dt><dd>${report().formats.join(' · ')}</dd></dl></div>`;}
function filtered(){if(S.qa.list==='empty')return [];let a=M.filterClients(S.search,S.filters,S.sort,S.direction);return S.selectedOnly?a.filter(c=>S.ids.includes(c.id)):a;}
function pageClients(){const a=filtered();S.page=Math.min(S.page,Math.max(1,Math.ceil(a.length/S.rows)));return a.slice((S.page-1)*S.rows,S.page*S.rows);}
function clientPane(){let r=report();return `<div class="row spread"><h2>Choose Client</h2>${S.ids.length?btn('Clear selection','clear-selection','ghost'):''}</div>${r.single?`<div class="notice" style="margin-top:12px">${r.name} supports one client at a time. Clear your selection to choose another client.</div>`:''}<div class="tabrow"><div class="tabs" role="tablist" aria-label="Client selection">${btn('All Clients ('+M.clients.length+')','client-tab','tab '+(S.clientTab==='all'?'on':''),'data-value="all" role="tab" aria-selected="'+(S.clientTab==='all')+'"')}${btn('Groups ('+M.groups.length+')','client-tab','tab '+(S.clientTab==='groups'?'on':''),'data-value="groups" role="tab" aria-selected="'+(S.clientTab==='groups')+'"')}</div></div><div class="client-tools"><input id="client-search" class="search" placeholder="Search by name, email or CRN" aria-label="Search clients" value="${esc(S.search)}" data-input="search">${btn(icon('filter')+' Filters'+(S.filters.length?' ('+S.filters.length+')':''),'filters','filterbutton','id="filter-trigger"')}</div>${S.filters.length?`<div class="row wrap" style="margin-bottom:12px"><span class="badge purple">${S.filters.length} active filter${S.filters.length>1?'s':''}</span>${btn('Clear filters','clear-filters','ghost')}</div>`:''}${S.clientTab==='all'?`<label class="checkline"><input type="checkbox" data-check="selectedOnly" ${S.selectedOnly?'checked':''}> Show selected clients only (${S.ids.length})</label>`:''}${S.listLoading||S.qa.list==='loading'?`<div aria-label="Loading clients" role="status">${Array.from({length:6},()=>'<div class="skeleton"></div>').join('')}<span class="muted">Loading clients…</span></div>`:S.clientTab==='groups'?groupList():clientTable()}`;}
function clientTable(){const list=pageClients(),a=filtered();if(!a.length)return `<div class="empty">${icon('users')}<h3>${S.selectedOnly?'No selected clients':'No clients found'}</h3><p>${S.qa.list==='empty'?'Your client list is empty in this scenario.':'Try a different search or clear the filters.'}</p>${btn('Reset search and filters','reset-search','ghost')}</div>`;let n=list.filter(c=>S.ids.includes(c.id)).length;return `<div class="table-shell"><table aria-label="Clients"><thead><tr><th style="width:32px"><input type="checkbox" aria-label="Select all clients on this page" data-check="page" ${n===list.length?'checked':''} ${report().single?'disabled':''}></th><th>${btn('Client details '+(S.sort==='name'?(S.direction===1?'↑':'↓'):''),'sort','table-sort','data-value="name"')}</th><th>${btn('Total current value ↕','sort','table-sort','data-value="current"')}</th><th>${btn('Total invested value ↕','sort','table-sort','data-value="invested"')}</th><th>MF Profile</th></tr></thead><tbody>${list.map(c=>`<tr class="${S.ids.includes(c.id)?'selected':''}"><td><input type="checkbox" aria-label="Select ${c.name}" data-check="client" data-id="${c.id}" ${S.ids.includes(c.id)?'checked':''} ${report().single&&S.ids.length&&!S.ids.includes(c.id)?'disabled':''}></td><td><div class="client-cell"><span class="avatar c${c.id%4}">${c.name[0]}</span><div><div class="client-name">${c.name}</div><small>${c.email||'No registered email'}</small><small>${c.crn}</small></div></div></td><td class="numbers">${money(c.current)}</td><td class="numbers">${money(c.invested)}</td><td><span class="badge ${c.profile==='Investment Ready'?'':'amber'}">${c.profile}</span></td></tr>`).join('')}</tbody></table></div>${n===list.length&&!report().single&&a.length>list.length?`<div class="notice" style="margin-top:10px">${n} clients on this page selected. ${btn('Select all '+a.length+' matching clients','select-all','ghost')}</div>`:''}<div class="pagination"><div class="row">${btn('‹','page','','aria-label="Previous page" data-value="'+(S.page-1)+'" '+(S.page===1?'disabled':''))}<span>Page <input aria-label="Go to page" type="number" min="1" max="${Math.ceil(a.length/S.rows)}" value="${S.page}" data-input="page"> of ${Math.ceil(a.length/S.rows)}</span>${btn('›','page','','aria-label="Next page" data-value="'+(S.page+1)+'" '+(S.page*S.rows>=a.length?'disabled':''))}</div><div class="row"><span>${a.length} clients</span><label>Rows <select aria-label="Rows per page" data-input="rows">${opt([10,20,50,100],S.rows)}</select></label></div></div>`;}
function groupList(){const gg=M.groups.filter(g=>!S.search||g.name.toLowerCase().includes(S.search.toLowerCase())||g.ids.some(id=>M.clients[id-1].name.toLowerCase().includes(S.search.toLowerCase())));return `<div class="groups">${gg.map((g)=>{const ids=g.ids.filter(id=>M.filterClients('',S.filters).some(c=>c.id===id));return `<div class="group"><label><input type="checkbox" data-check="group" data-id="${M.groups.indexOf(g)}" ${ids.length&&ids.every(id=>S.ids.includes(id))?'checked':''} ${report().single||!ids.length?'disabled':''}>${g.name}</label><p>${ids.length} matching clients</p><details><summary>View members</summary>${ids.map(id=>`<label class="checkline"><input type="checkbox" aria-label="Select ${M.clients[id-1].name} from group" data-check="client" data-id="${id}" ${S.ids.includes(id)?'checked':''} ${report().single&&S.ids.length&&!S.ids.includes(id)?'disabled':''}>${M.clients[id-1].name}</label>`).join('')}</details></div>`}).join('')}</div>${gg.length?'':'<div class="empty">No matching groups.</div>'}`;}
function pills(label,key,values,value,disabled=false){return `<div class="field"><div class="label" id="label-${key}">${label}</div><div class="pills" role="group" aria-labelledby="label-${key}">${values.map(v=>btn(esc(v),'config-pill','pill '+(v===value?'on':''),`data-key="${key}" data-value="${esc(v)}" aria-pressed="${v===value}" ${disabled?'disabled':''}`)).join('')}</div></div>`;}
function inputField(label,key,type='text',placeholder='',extra=''){return `<div class="field"><label for="cfg-${key}">${label}</label><input id="cfg-${key}" type="${type}" data-config="${key}" value="${esc(S.config[key])}" placeholder="${esc(placeholder)}" ${extra}></div>`;}
function selectField(label,key,values){return `<div class="field"><label for="cfg-${key}">${label}</label><select id="cfg-${key}" data-config="${key}">${opt(values,S.config[key])}</select></div>`;}
function configuration(){const r=report(),c=S.config;let html='';if(!r.business){html+=`<div class="field"><div class="label">Delivery method</div><div class="delivery" role="group" aria-label="Delivery method">${['Email now','Download','Schedule'].map(d=>btn(icon(d==='Email now'?'mail':d==='Download'?'download':'clock')+d,'delivery',c.delivery===d?'on':'',`data-value="${d}" aria-pressed="${c.delivery===d}" ${S.edit?'disabled':''}`)).join('')}</div><small>${c.delivery==='Download'?'Generate files and download them here.':c.delivery==='Email now'?"Send once to each client’s registered email.":'Email reports automatically on a recurring schedule.'}</small></div>`;}if(S.edit)html+='<div class="notice" style="margin-bottom:18px">Change recipients, frequency, period and name. Report and format remain unchanged.</div>';
 html+=pills('Format','format',r.formats,c.format,!!S.edit);
 if(r.kind==='period'){html+=pills('Date window','period',c.delivery==='Schedule'?M.periods.slice(0,7):M.periods,c.period);if(c.period==='Custom range')html+=`<div class="field-grid">${inputField('From date','from','date')}${inputField('To date','to','date')}</div>`;}
 if(r.kind==='snapshot'){html+=pills('Date window','snapshot',c.delivery==='Schedule'?['As on run date']:['As on run date','As on a fixed date'],c.snapshot);if(c.delivery!=='Schedule'&&c.snapshot==='As on a fixed date')html+=inputField('Report date','fixed','date');else html+='<p class="helper" style="margin:-10px 0 18px">'+(c.delivery==='Schedule'?'Uses the date each scheduled report runs.':'Uses the date this report is generated.')+'</p>';}
 if(r.kind==='year')html+=selectField('Financial year','year',['',...Array.from({length:12},(_,i)=>`${2015+i}–${String(2016+i).slice(2)}`)]);
 if(r.id==='folio')html+=inputField('Folio number','folio','text','e.g. 12345678/90')+'<p class="helper" style="margin:-10px 0 18px">Enter the selected client’s folio number.</p>';
 if(r.id==='pms'&&c.delivery!=='Schedule')html+=inputField('Account opening date','opening','date','',`max="${M.today}"`);
 if(r.id==='holdings')html+=`<div class="field"><div class="label">Include in report</div><label class="checkline"><input type="checkbox" data-config="cashflows" ${c.cashflows?'checked':''}>Include Cashflows</label><label class="checkline"><input type="checkbox" data-config="transactions" ${c.transactions?'checked':''}>Include Transaction Summary</label></div>`;
 if(c.delivery==='Schedule'){html+=`<hr class="divider">${pills('Frequency','frequency',M.frequencies,c.frequency)}`;if(c.frequency==='Weekly')html+=selectField('Day of week','weekday',['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']);if(['Monthly','Quarterly'].includes(c.frequency))html+=selectField('Day of month','day',Array.from({length:28},(_,i)=>String(i+1)));if(c.frequency==='Quarterly')html+='<p class="helper" style="margin-top:-12px;margin-bottom:18px">Runs in January, April, July and October.</p>';if(c.frequency==='Annually')html+=selectField('Month','month',M.months)+'<p class="helper" style="margin-top:-12px;margin-bottom:18px">Runs on the 1st of the selected month.</p>';html+=`<div class="field"><div class="label">Time</div><div class="field-grid"><label class="small-label">Hour<select aria-label="Hour" data-config="hour">${opt(Array.from({length:24},(_,i)=>String(i).padStart(2,'0')),c.hour)}</select></label><label class="small-label">Minute<select aria-label="Minute" data-config="minute">${opt(Array.from({length:12},(_,i)=>String(i*5).padStart(2,'0')),c.minute)}</select></label></div></div>${inputField('Schedule name','name','text','e.g. Monthly portfolio update','maxlength="100"')}`;if(S.notice)html+=`<p class="notice" style="margin-bottom:16px">${esc(S.notice)}</p>`;}
 html+=`<div class="validation" aria-live="polite">${validationHTML()}</div>`;return html;}
function validationHTML(){const errors=M.validate(report(),S.config,S.ids).filter(x=>x!=='Select at least one client.');return errors.length?`<div class="notice error">${errors.map(esc).join('<br>')}</div>`:'';}
function selectedSummary(){if(report().business)return `<div class="selected-box"><strong>Scope</strong><p class="helper">All business data available to your account.</p></div>`;return `<details class="selected-box" open><summary>${countLabel()} selected</summary>${!S.ids.length?'<p class="helper">Choose clients from the list to get started.</p>':`<div class="selected-list">${chosen().map(c=>`<div class="selected-item"><span class="avatar c${c.id%4}">${c.name[0]}</span><div class="identity">${c.name}<small>${S.config.delivery==='Download'?c.crn:c.email||'No registered email'}</small></div>${btn(icon('close'),'remove-client','icon-btn',`data-id="${c.id}" aria-label="Remove ${c.name}"`)}</div>`).join('')}</div>`}${report().id==='family'&&S.ids.length?'<p class="helper">Family report scope follows each selected client’s family membership.</p>':''}</details>`;}
function summaryPairs(r=report(),c=S.config){let p=[['Report',r.name],['Delivery',c.delivery],['Format',c.format]];if(r.kind==='period')p.push(['Date window',c.period==='Custom range'?`${c.from||'—'} → ${c.to||'—'}`:c.period]);if(r.kind==='snapshot')p.push(['Date window',c.snapshot==='As on a fixed date'?c.fixed||'Choose a date':'As on run date']);if(r.kind==='year')p.push(['Financial year',c.year||'Choose a year']);if(r.id==='folio')p.push(['Folio',c.folio||'Required']);if(r.id==='pms'&&c.delivery!=='Schedule')p.push(['Account opened',c.opening||'Required']);if(r.id==='holdings')p.push(['Cashflows',c.cashflows?'Included':'Not included'],['Transaction summary',c.transactions?'Included':'Not included']);if(c.delivery==='Schedule')p.push(['Name',c.name||'Required'],['Frequency',c.frequency],['When',c.frequency==='Weekly'?c.weekday:['Monthly','Quarterly'].includes(c.frequency)?'Day '+c.day:c.frequency==='Annually'?'1 '+c.month:'Every day'],['Time',c.hour+':'+c.minute]);return p;}
function reviewSummary(){return `<details class="review-box"><summary>Review configuration</summary><dl class="summary-lines">${summaryPairs().map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`;}
function actionLabel(){return S.edit?'Save changes':S.config.delivery==='Download'?'Generate & download':S.config.delivery==='Email now'?'Send '+S.ids.length+' email'+(S.ids.length===1?'':'s'):'Create schedule';}
function actionFooter(modal){let valid=M.validate(report(),S.config,S.ids).length===0;const hint=!S.ids.length&&!report().business?'Select a client to continue.':!valid?'Complete the required settings.':S.config.delivery==='Schedule'?'Reports go to registered client emails.':S.config.delivery==='Email now'?'Recipients shown above.':'Files will be available in History.';return `${modal?btn(report().business?'Back':'Back to clients','close-config','ghost'):btn('Settings ↑','jump-settings','ghost mobile-settings')}<div class="helper" id="action-hint">${hint}</div>${btn(actionLabel(),'submit','primary',`id="submit-report" ${!valid||S.busy?'disabled':''}`)}`;}

function pagedRows(rows,key){const p=S.records[key];p.page=Math.max(1,Math.min(p.page,Math.ceil(rows.length/p.rows)||1));return rows.slice((p.page-1)*p.rows,p.page*p.rows);}
function recordPager(rows,key){const p=S.records[key],pages=Math.max(1,Math.ceil(rows.length/p.rows));return `<div class="pagination"><div class="row">${btn('Previous','record-page','','data-key="'+key+'" data-value="'+(p.page-1)+'" '+(p.page===1?'disabled':''))}<span>Page <input aria-label="Go to ${key} page" type="number" min="1" max="${pages}" value="${p.page}" data-record="${key}" data-record-field="page"> of ${pages}</span>${btn('Next','record-page','','data-key="'+key+'" data-value="'+(p.page+1)+'" '+(p.page===pages?'disabled':''))}</div><label>Rows <select aria-label="${key} rows per page" data-record="${key}" data-record-field="rows">${opt([10,20,50,100],p.rows)}</select></label></div>`;}

function scheduleTable(){if(!S.schedules.length)return `<div class="empty">${icon('clock')}<h3>No schedules yet</h3><p>Choose a report and select Schedule to create one.</p>${btn('Choose a report','tab','primary','data-value="all"')}</div>`;const items=pagedRows(S.schedules,'schedules');return `<div class="table-shell"><table aria-label="Schedules"><thead><tr><th>Report</th><th>Clients</th><th>Format</th><th>Frequency</th><th>Next run</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(j=>`<tr><td><strong>${esc(j.config.name)}</strong><small style="display:block">${M.reports.find(r=>r.id===j.report).name}</small></td><td>${j.ids.length}</td><td>${j.config.format}</td><td>${j.config.frequency}</td><td>${j.status==='Paused'?'—':M.nextRuns(j.config)[0]}</td><td><span class="badge ${j.status==='Paused'?'amber':''}">${j.status}</span></td><td><select aria-label="Actions for ${esc(j.config.name)}" data-schedule="${j.id}"><option value="">Actions…</option><option value="run">Run now</option><option value="edit">Edit schedule</option><option value="pause">${j.status==='Paused'?'Resume':'Pause'}</option><option value="delete">Delete</option></select></td></tr>`).join('')}</tbody></table></div>${recordPager(S.schedules,'schedules')}`;}
function historyTable(){const all=S.history.filter(j=>j.business===(S.category==='business')),hh=pagedRows(all,'history');if(!hh.length)return `<div class="empty">${icon()}<h3>No reports generated yet</h3><p>Your completed report requests will appear here.</p>${btn('Choose a report','tab','primary','data-value="all"')}</div>`;return `<div class="table-shell"><table aria-label="Report history"><thead><tr><th>Report</th><th>Clients</th><th>Delivery</th><th>Format</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody>${hh.map(j=>`<tr><td>${M.reports.find(r=>r.id===j.report).name}</td><td>${j.business?'Business':j.ids.length}</td><td>${j.config.delivery}</td><td>${j.config.format}</td><td>${j.created}</td><td><span class="badge ${j.results.some(x=>x.status==='Failed')?'red':''}">${jobStatus(j)}</span></td><td>${btn(S.expanded===j.id?'Hide':'View','history-details','ghost',`data-id="${j.id}" aria-expanded="${S.expanded===j.id}"`)}</td></tr>${S.expanded===j.id?`<tr><td colspan="7" class="history-detail"><dl class="summary-lines">${summaryPairs(M.reports.find(r=>r.id===j.report),j.config).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${resultRows(j)}${j.results.some(x=>x.status==='Failed')?btn('Retry failed reports','retry','outline',`data-id="${j.id}"`):''}</td></tr>`:''}`).join('')}</tbody></table></div>${recordPager(all,'history')}`;}
function jobStatus(j){return j.results.every(x=>x.status==='Failed')?'Failed':j.results.some(x=>x.status==='Failed')?'Partially completed':j.results.every(x=>x.status==='No data')?'No data':j.config.delivery==='Download'?'Ready':'Sent';}
function resultRows(j){return j.results.map((x,i)=>`<div class="result-row"><div><strong>${x.client===0?'Business report':M.clients.find(c=>c.id===x.client).name}</strong><small>${x.status==='Failed'?'Generation failed. Retry with the same configuration.':x.status==='No data'?'No eligible records for this period.':j.config.delivery==='Download'?j.config.format+' · Ready to download':M.clients.find(c=>c.id===x.client)?.email||'Business scope'}</small></div><div class="row"><span class="badge ${x.status==='Failed'?'red':x.status==='No data'?'amber':''}">${x.status}</span>${x.status==='Ready'?btn(icon('download'),'download-file','icon-btn',`data-id="${j.id}" data-index="${i}" aria-label="Download sample for ${x.client===0?'business':M.clients[x.client-1].name}"`):''}</div></div>`).join('');}
function configModal(){return `<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${S.edit?'Edit schedule':'Configure report'}</h2><small>${report().name}</small></div>${btn(icon('close'),'close-config','icon-btn','aria-label="Close configuration"')}</header><div class="modal-scroll" id="modal-scroll"><div class="modal-columns"><div>${configuration()}</div><aside class="modal-aside">${selectedSummary()}${reviewSummary()}<p class="helper">${report().business?'Your business-wide export is generated as one file.':S.config.delivery==='Schedule'?'A separate report is sent to each selected client.':S.config.delivery==='Email now'?'Reports are emailed separately to registered client addresses.':'Each selected client receives a separate report file.'}</p></aside></div></div><footer class="modal-footer">${actionFooter(true)}</footer></div>`;}
function filterModal(){return `<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">Filter clients</h2><small>Clients must match all conditions.</small></div>${btn(icon('close'),'close','icon-btn','aria-label="Close filters"')}</header><div class="modal-scroll">${S.draftFilters.map((f,i)=>{let field=M.fields.find(x=>x[0]===f.field),type=field[2];return `<div class="filter-row"><select aria-label="Filter field ${i+1}" data-filter="field" data-index="${i}">${M.fields.map(x=>`<option value="${x[0]}" ${x[0]===f.field?'selected':''}>${x[1]}</option>`).join('')}</select><select aria-label="Filter operator ${i+1}" data-filter="op" data-index="${i}">${[['eq','Equal to'],['neq','Not equal to'],...(['number','date'].includes(type)?[['lte','Less than or equal'],['gte','Greater than or equal']]:[['contains','Contains']])].map(([v,l])=>`<option value="${v}" ${f.op===v?'selected':''}>${l}</option>`).join('')}</select>${['profile','tracker'].includes(type)?`<select aria-label="Filter value ${i+1}" data-filter="value" data-index="${i}">${opt(type==='profile'?['Investment Ready','Not Submitted']:['Synced','Not synced'],f.value)}</select>`:`<input aria-label="Filter value ${i+1}" type="${type==='number'?'number':type==='date'?'date':'text'}" data-filter="value" data-index="${i}" value="${esc(f.value)}" placeholder="Enter value">`}${btn(icon('close'),'remove-filter','icon-btn',`data-index="${i}" aria-label="Remove filter ${i+1}"`)}</div>`}).join('')}${btn('+ Add condition','add-filter','ghost')}</div><footer class="modal-footer">${btn('Clear all','clear-draft-filters','ghost')}${btn('Apply filters','apply-filters','primary')}</footer></div>`;}
function controlsModal(){return `<div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">Prototype controls</h2><small>For design review only</small></div>${btn(icon('close'),'close','icon-btn','aria-label="Close prototype controls"')}</header><div class="modal-scroll help-content"><p>All clients are fictional. Actions are simulated locally. No report or email is sent to Wealthy.</p><div class="qa"><label>Next report outcome<select aria-label="Next report outcome" data-qa="outcome">${[['success','Success'],['failure','Generation failed'],['partial','Partial success (multiple clients)'],['nodata','No data']].map(([v,l])=>`<option value="${v}" ${S.qa.outcome===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="qa"><label>Client list state<select aria-label="Client list state" data-qa="list">${[['normal','Normal'],['empty','Empty list'],['loading','Loading']].map(([v,l])=>`<option value="${v}" ${S.qa.list===v?'selected':''}>${l}</option>`).join('')}</select></label></div><h3>Useful examples</h3><p class="helper">Folio: 12345678/90 · PMS opening: 1 April 2020. Riya Sen has no email to test recipient validation. Neha Sharma has a zero portfolio. These are fixtures, not real accounts.</p><p class="helper">Calendar reference: 15 October 2026. Recurrence preview in Schedules is illustrative; the live service’s timezone was not exposed.</p><a href="coverage.html" target="_blank">Capability coverage and limitations ↗</a></div><footer class="modal-footer">${btn('Reset demo data','reset-demo','ghost')}${btn('Done','close','primary')}</footer></div>`;}
function resultModal(){const j=S.result;if(S.busy)return `<div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="loading" role="status"><div class="spinner"></div><h2 id="modal-title">${S.config.delivery==='Schedule'&&!S.runningSchedule?'Saving schedule…':'Preparing your reports…'}</h2><p class="muted">${report().name}</p><p class="helper">Keep this window open. Your selection is saved.</p></div></div>`;
 if(j?.schedule)return `<div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${S.edit?'Schedule updated':'Schedule created'}</h2>${btn(icon('close'),'finish','icon-btn','aria-label="Close result"')}</header><div class="modal-scroll"><div class="result-heading"><div class="result-icon">✓</div><h3>${esc(j.config.name)}</h3><p class="muted">${countLabel(j.ids.length)} · ${j.config.frequency} · ${j.config.hour}:${j.config.minute}</p></div><div class="notice success">Your schedule has been saved in this prototype.</div><dl class="summary-lines">${summaryPairs().map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><small>Prototype only. No recurring delivery has been activated.</small></div><footer class="modal-footer">${btn('Create another report','finish','ghost')}${btn('View schedules','view-schedules','primary')}</footer></div>`;
 return `<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${jobStatus(j)==='Failed'?'Report generation failed':jobStatus(j)==='Partially completed'?'Some reports need attention':jobStatus(j)==='No data'?'No data for this report':j.config.delivery==='Download'?'Your reports are ready':'Reports sent'}</h2><small>${M.reports.find(r=>r.id===j.report).name} · ${j.config.format}</small></div>${btn(icon('close'),'finish','icon-btn','aria-label="Close result"')}</header><div class="modal-scroll"><p class="notice ${j.results.some(x=>x.status==='Failed')?'error':'success'}">${j.results.some(x=>x.status==='Failed')?'Your configuration is saved. Retry failed items without selecting clients again.':j.config.delivery==='Download'?'Download your sample files below. They remain available in History.':'Email delivery simulated successfully. No real email was sent.'}</p>${resultRows(j)}${j.results.some(x=>x.status==='Failed')?`<p class="helper">Reference: DEMO-${j.id}. This scenario is simulated.</p>`:''}</div><footer class="modal-footer">${btn('View history','view-history','ghost')}${j.config.delivery==='Download'&&j.results.filter(x=>x.status==='Ready').length>1?btn('Download all (.zip)','download-all','outline',`data-id="${j.id}"`):''}${j.results.some(x=>x.status==='Failed')?btn('Retry failed reports','retry','primary',`data-id="${j.id}"`):btn('Done','finish','primary')}</footer></div>`;}
function renderOverlay(focus=false){const root=$('#overlay-root');let html='';if(S.modal==='config')html=configModal();if(S.modal==='filters')html=filterModal();if(S.modal==='controls')html=controlsModal();if(S.modal==='result')html=resultModal();if(S.modal==='selected')html=`<div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">Selected clients</h2>${btn(icon('close'),'close','icon-btn','aria-label="Close selected clients"')}</header><div class="modal-scroll">${selectedSummary()}</div><footer class="modal-footer">${btn('Done','close','primary')}</footer></div>`;if(S.modal==='delete')html=`<div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">Delete schedule?</h2></header><div class="modal-scroll"><p>“${esc(S.schedules.find(j=>j.id===S.deleteId)?.config.name)}” will stop running and be removed from this demo.</p></div><footer class="modal-footer">${btn('Keep schedule','close','ghost')}${btn('Delete schedule','confirm-delete','primary')}</footer></div>`;root.innerHTML=html?`<div class="overlay">${html}</div>`:'';$('#app').inert=!!html;document.body.style.overflow=html?'hidden':'';if(focus&&html)requestAnimationFrame(()=>root.querySelector('button:not([disabled]),input,select,[tabindex]')?.focus());}
function render(){const active=document.activeElement,aid=active?.id,sel=active&&['text','search'].includes(active.type)?active.selectionStart:null;const ps=$('#panel-scroll')?.scrollTop,ms=$('#modal-scroll')?.scrollTop;$('#app').innerHTML=shell();renderOverlay();if(ps!=null&&$('#panel-scroll'))$('#panel-scroll').scrollTop=ps;if(ms!=null&&$('#modal-scroll'))$('#modal-scroll').scrollTop=ms;if(aid){const e=document.getElementById(aid);e?.focus({preventScroll:true});if(sel!=null&&e?.setSelectionRange)e.setSelectionRange(sel,sel);}const pageCB=document.querySelector('[data-check="page"]');if(pageCB){const a=pageClients(),n=a.filter(c=>S.ids.includes(c.id)).length;pageCB.indeterminate=n>0&&n<a.length;}}
function updateValidation(){document.querySelectorAll('.validation').forEach(e=>e.innerHTML=validationHTML());const b=$('#submit-report');if(b)b.disabled=M.validate(report(),S.config,S.ids).length>0;const foot=document.querySelector(S.modal==='config'?'.modal-footer':'.panel-footer');if(foot)foot.innerHTML=actionFooter(S.modal==='config');document.querySelectorAll('.review-box').forEach(e=>{const isOpen=e.open;const box=document.createElement('div');box.innerHTML=reviewSummary();e.replaceWith(box.firstElementChild);document.querySelectorAll('.review-box').forEach(x=>x.open=isOpen);});}
function submit(){if(S.busy||M.validate(report(),S.config,S.ids).length)return;S.busy=true;S.modal='result';S.result=null;renderOverlay(true);const r=report(),config=structuredClone(S.config),ids=[...S.ids];setTimeout(()=>{if(config.delivery==='Schedule'&&!S.runningSchedule){const j={id:S.edit||'s'+Date.now(),report:r.id,ids,config,status:'Active'};const old=S.schedules.findIndex(x=>x.id===S.edit);if(old>=0)S.schedules[old]={...j,status:S.schedules[old].status};else S.schedules.unshift(j);S.result={...j,schedule:true};}else{const outcome=S.qa.outcome;const j={id:'j'+Date.now(),report:r.id,business:r.business,ids,config,created:'15 Oct 2026 · '+new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),results:(r.business?[0]:ids).map((id,i)=>({client:id,status:outcome==='failure'||outcome==='partial'&&i===0?'Failed':outcome==='nodata'?'No data':config.delivery==='Download'?'Ready':'Sent'}))};S.history.unshift(j);S.result=j;}S.busy=false;S.runningSchedule=false;persist();renderOverlay(true);},1000);}
function finish(tab='all'){S.screen='catalog';S.tab=tab;S.modal=null;S.result=null;S.edit=null;S.ids=[];S.config=null;render();window.scrollTo(0,0);}
function retry(id){let j=S.history.find(x=>x.id===id);S.report=j.report;S.config=structuredClone(j.config);S.ids=[...j.ids];S.result=j;S.busy=true;S.modal='result';renderOverlay(true);setTimeout(()=>{j.results=j.results.map(x=>x.status==='Failed'?{...x,status:j.config.delivery==='Download'?'Ready':'Sent'}:x);S.busy=false;persist();renderOverlay(true);},900);}
function sampleFile(j,index){let r=M.reports.find(x=>x.id===j.report),client=j.results[index].client,name=client?M.clients[client-1].name:'Business';const rows=[['WEALTHY PROTOTYPE SAMPLE - NOT A FINANCIAL STATEMENT'],['Report',r.name],['Client',name],['Date',M.today],...summaryPairs(r,j.config),['Notice','Fictional demonstration output only.']];let blob,ext;if(j.config.format==='PDF'){blob=samplePDF(rows.map(x=>x.join(': ')));ext='pdf';}else if(j.config.format==='Excel'){blob=sampleXLSX(rows);ext='xlsx';}else{blob=new Blob(['\ufeff'+rows.map(x=>x.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});ext='csv';}return {blob,name:`sample-${r.id}-${name.replaceAll(' ','-')}-${M.today}.${ext}`};}
async function downloadAll(id){const j=S.history.find(x=>x.id===id),files={};for(let i=0;i<j.results.length;i++){if(j.results[i].status!=='Ready')continue;const f=sampleFile(j,i);files[f.name]=new Uint8Array(await f.blob.arrayBuffer());}const blob=zipStore(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sample-'+j.report+'-'+M.today+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Sample ZIP download started.');}
function downloadFile(id,index){let j=S.history.find(x=>x.id===id),r=M.reports.find(x=>x.id===j.report),client=j.results[index].client,name=client?M.clients[client-1].name:'Business';const rows=[['WEALTHY PROTOTYPE SAMPLE - NOT A FINANCIAL STATEMENT'],['Report',r.name],['Client',name],['Date',M.today],...summaryPairs(r,j.config),['Notice','Fictional demonstration output only.']];let blob,ext;if(j.config.format==='PDF'){blob=samplePDF(rows.map(x=>x.join(': ')));ext='pdf';}else if(j.config.format==='Excel'){blob=sampleXLSX(rows);ext='xlsx';}else{blob=new Blob(['\ufeff'+rows.map(x=>x.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});ext='csv';}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sample-${r.id}-${name.replaceAll(' ','-')}-${M.today}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Sample download started. This is not a financial statement.');}
function samplePDF(lines){const clean=s=>s.replace(/[^\x20-\x7E]/g,'-').replace(/[\\()]/g,'\\$&');let stream='BT /F1 12 Tf 50 790 Td '+lines.map((l,i)=>(i?'0 -24 Td ':'')+'('+clean(l)+') Tj').join('\n')+' ET';let objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`],pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`;});let start=pdf.length;pdf+=`xref\n0 6\n0000000000 65535 f \n`+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+`trailer << /Size 6 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'});}
function zipStore(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;const crc=b=>{let c=-1;for(let v of b){c^=v;for(let i=0;i<8;i++)c=c>>>1^((c&1)?0xedb88320:0);}return(c^-1)>>>0;};for(const [name,data] of Object.entries(files)){const n=enc.encode(name),d=typeof data==='string'?enc.encode(data):data,check=crc(d),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint32(14,check,true);v.setUint32(18,d.length,true);v.setUint32(22,d.length,true);v.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,d);const c=new Uint8Array(46+n.length),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint32(16,check,true);w.setUint32(20,d.length,true);w.setUint32(24,d.length,true);w.setUint16(28,n.length,true);w.setUint32(42,offset,true);c.set(n,46);central.push(c);offset+=h.length+d.length;}const size=central.reduce((a,b)=>a+b.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,central.length,true);v.setUint16(10,central.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
function sampleXLSX(rows){return zipStore({'[Content_Types].xml':'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Prototype sample" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="1" width="40" customWidth="1"/><col min="2" max="2" width="65" customWidth="1"/></cols><sheetData>'+rows.map((row,i)=>`<row r="${i+1}">`+row.map((v,k)=>`<c r="${String.fromCharCode(65+k)}${i+1}" t="inlineStr"><is><t>${esc(v)}</t></is></c>`).join('')+'</row>').join('')+'</sheetData></worksheet>'});}
function changeDelivery(value){const prev=S.config.delivery;S.config.delivery=value;S.notice='';if(value==='Schedule'){if(report().kind==='period')S.config.period='Last month';if(report().kind==='snapshot')S.config.snapshot='As on run date';}else if(prev==='Schedule'&&report().kind==='period')S.config.period='Last 7 days';render();}
function toggleClient(id,checked){if(checked){if(report().single&&S.ids.length&&!S.ids.includes(id)){toast('This report supports one client at a time.');return;}if(!S.ids.includes(id))S.ids.push(id);}else S.ids=S.ids.filter(x=>x!==id);render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,v=b.dataset.value,id=b.dataset.id;switch(a){
 case 'report':openReport(v);break;
 case 'category':S.category=v;S.tab='all';S.catalogSearch='';render();break;
 case 'tab':S.tab=v;render();break;
 case 'clear-catalog':S.catalogSearch='';render();break;
 case 'back':S.screen='catalog';S.modal=null;S.edit=null;S.tab='all';render();break;
 case 'client-tab':S.clientTab=v;S.page=1;render();break;
 case 'page':S.page=Number(v);render();break;
 case 'record-page':S.records[b.dataset.key].page=Number(v);render();break;
 case 'sort':S.direction=S.sort===v?-S.direction:1;S.sort=v;render();break;
 case 'remove-client':toggleClient(Number(id),false);break;
 case 'clear-selection':S.ids=[];render();break;
 case 'select-all':S.ids=[...new Set([...S.ids,...filtered().map(c=>c.id)])];render();break;
 case 'reset-search':S.search='';S.filters=[];S.selectedOnly=false;S.page=1;render();break;
 case 'clear-filters':S.filters=[];S.page=1;render();break;
 case 'configure':if(report().business||S.ids.length)showModal('config');break;
 case 'review-selected':showModal('selected');break;
 case 'delivery':changeDelivery(v);break;
 case 'config-pill':S.config[b.dataset.key]=v;if(b.dataset.key==='frequency'&&report().kind==='period'){const p={Daily:'Last 7 days',Weekly:'Last 7 days',Monthly:'Last month',Quarterly:'Last quarter',Annually:'Previous FY'};S.config.period=p[v];S.notice='Date window updated to '+p[v]+' for '+v.toLowerCase()+' delivery. You can choose a different window above.';}render();break;
 case 'submit':submit();break;
 case 'jump-settings':document.getElementById('configuration-panel')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'close-config':S.modal=null;render();$('#configure-trigger')?.focus();break;
 case 'close':closeModal();render();break;
 case 'controls':S.returnModal=S.modal;showModal('controls');break;
 case 'filters':S.draftFilters=structuredClone(S.filters.length?S.filters:[{field:'current',op:'lte',value:''}]);showModal('filters');break;
 case 'add-filter':S.draftFilters.push({field:'current',op:'lte',value:''});renderOverlay();break;
 case 'remove-filter':S.draftFilters.splice(Number(b.dataset.index),1);renderOverlay();break;
 case 'clear-draft-filters':S.draftFilters=[];renderOverlay();break;
 case 'apply-filters':S.filters=structuredClone(S.draftFilters.filter(f=>f.value!==''));S.page=1;S.modal=null;render();break;
 case 'history-details':S.expanded=S.expanded===id?null:id;render();break;
 case 'download-file':downloadFile(id,Number(b.dataset.index));break;
 case 'download-all':downloadAll(id);break;
 case 'retry':retry(id);break;
 case 'finish':finish();break;
 case 'view-history':finish('history');break;
 case 'view-schedules':finish('schedules');break;
 case 'confirm-delete':S.schedules=S.schedules.filter(j=>j.id!==S.deleteId);S.modal=null;persist();render();toast('Schedule deleted from this demo.');break;
 case 'reset-demo':S.history=[];S.schedules=[structuredClone(initialSchedule)];S.qa={outcome:'success',list:'normal'};persist();S.modal=null;S.screen='catalog';S.tab='all';render();toast('Demo data reset.');break;
 }});
document.addEventListener('change',e=>{const t=e.target;
 if(t.dataset.record){S.records[t.dataset.record][t.dataset.recordField]=Number(t.value)||1;if(t.dataset.recordField==='rows')S.records[t.dataset.record].page=1;render();return;}
 if(t.dataset.check){const k=t.dataset.check;if(k==='client')toggleClient(Number(t.dataset.id),t.checked);else if(k==='page'){const ids=pageClients().map(c=>c.id);S.ids=t.checked?[...new Set([...S.ids,...ids])]:S.ids.filter(id=>!ids.includes(id));render();}else if(k==='group'){const ids=M.groups[Number(t.dataset.id)].ids.filter(id=>M.filterClients('',S.filters).some(c=>c.id===id));S.ids=t.checked?[...new Set([...S.ids,...ids])]:S.ids.filter(id=>!ids.includes(id));render();}else{S.selectedOnly=t.checked;S.page=1;render();}return;}
 if(t.dataset.config){S.config[t.dataset.config]=t.type==='checkbox'?t.checked:t.value;if(t.type==='checkbox'||t.tagName==='SELECT'||t.type==='date')render();return;}
 if(t.dataset.input==='rows'){S.rows=Number(t.value);S.page=1;render();return;}if(t.dataset.input==='page'){S.page=Math.max(1,Math.min(Math.ceil(filtered().length/S.rows),Number(t.value)||1));render();return;}
 if(t.dataset.filter){const f=S.draftFilters[Number(t.dataset.index)];f[t.dataset.filter]=t.value;if(t.dataset.filter==='field'){const type=M.fields.find(x=>x[0]===t.value)[2];f.op=['number','date'].includes(type)?'lte':'eq';f.value=type==='profile'?'Investment Ready':type==='tracker'?'Synced':'';renderOverlay();}return;}
 if(t.dataset.qa){S.qa[t.dataset.qa]=t.value;return;}
 if(t.dataset.schedule){const j=S.schedules.find(x=>x.id===t.dataset.schedule),action=t.value;t.value='';if(action==='pause'){j.status=j.status==='Active'?'Paused':'Active';persist();render();toast(j.status==='Paused'?'Schedule paused.':'Schedule resumed.');}if(action==='delete'){S.deleteId=j.id;showModal('delete');}if(action==='edit'){S.report=j.report;S.ids=[...j.ids];S.config=structuredClone(j.config);S.edit=j.id;S.screen='work';S.search='';S.filters=[];S.clientTab='all';S.selectedOnly=false;S.page=1;S.notice='';S.modal=V===2?'config':null;render();if(S.modal)renderOverlay(true);}if(action==='run'){S.report=j.report;S.ids=[...j.ids];S.config={...structuredClone(j.config),delivery:'Email now'};S.edit=null;S.runningSchedule=true;submit();}return;}
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.input&&['search','catalogSearch'].includes(t.dataset.input)){S[t.dataset.input]=t.value;S.page=1;render();}if(t.dataset.config&&t.type!=='checkbox'&&t.tagName!=='SELECT'){S.config[t.dataset.config]=t.value;updateValidation();}if(t.dataset.filter==='value')S.draftFilters[Number(t.dataset.index)].value=t.value;});
document.addEventListener('keydown',e=>{if(!S.modal)return;if(e.key==='Escape'){e.preventDefault();if(S.busy)return;if(S.modal==='config'){S.modal=null;render();$('#configure-trigger')?.focus();}else if(S.modal==='result')finish();else{closeModal();render();}return;}if(e.key==='Tab'){const root=$('#overlay-root'),f=[...root.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href],summary')].filter(x=>x.offsetParent!==null);if(!f.length){e.preventDefault();return;}const first=f[0],last=f[f.length-1];if(e.shiftKey&&(document.activeElement===first||!root.contains(document.activeElement))){last.focus();e.preventDefault();}else if(!e.shiftKey&&(document.activeElement===last||!root.contains(document.activeElement))){first.focus();e.preventDefault();}}});
render();
let panelSizing=false;
function sizePanel(){panelSizing=false;const p=document.querySelector('.panel');if(!p)return;if(innerWidth>900){const top=Math.max(120,p.getBoundingClientRect().top);p.style.height=Math.max(350,innerHeight-top-24)+'px';}else p.style.height='';}
window.addEventListener('scroll',()=>{if(!panelSizing){panelSizing=true;requestAnimationFrame(sizePanel);}},{passive:true});window.addEventListener('resize',sizePanel);
new MutationObserver(()=>requestAnimationFrame(sizePanel)).observe(document.getElementById('app'),{childList:true});
